#[path="../../../../../crates/proto/src/probe.rs"]mod probe;
use std::time::{Duration,Instant};
fn main(){let mut seed=17u64;for cap in [1000u64,5000,20000,100000,500000]{for n in [6u8,16]{let mut rates=vec![];let mut zero=0;let mut slow=0;let mut prev=false;let mut pairs=0;for _ in 0..10000{let t=Instant::now();let mut events=vec![];for i in 0..n{seed^=seed>>12;seed^=seed<<25;seed^=seed>>27;let jitter=seed.wrapping_mul(0x2545f4914f6cdd1d)%4000000;let at=u64::from(i)*10240000000/cap+jitter;events.push((at,i));}events.sort();let mut m=probe::TrainMeter::default();for(at,i)in events{m.push(1,i,n,1200,t+Duration::from_nanos(at));}let v=m.take_kbps(t+Duration::from_secs(1));zero+=u32::from(v==0);let low=v>0&&v<cap as u32*3/4;slow+=u32::from(low);pairs+=u32::from(low&&prev);prev=low;if v>0{rates.push(v)}}rates.sort();println!("cap={cap} n={n} jitter=0..4ms trials=10000 zero={zero} false_slow={slow} consecutive_false={pairs} valid_p50={} valid_p95={}",rates.get(rates.len()/2).copied().unwrap_or(0),rates.get(rates.len()*95/100).copied().unwrap_or(0));}}}
